// Some portions generated by Claude Code

package org.eclipse.rdf4j.sail.lmdb.util;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Arrays;
import java.util.SplittableRandom;

import org.eclipse.rdf4j.sail.lmdb.Chunks;
import org.junit.jupiter.api.Test;

/**
 * Randomized round-trip characterization of {@link ChunkInput} against {@link ChunkOutput}. Covers all value column
 * encodings (constant, packed, varint), signed deltas, every varint length, chunks spanning several decode blocks, heap
 * and direct buffers in both byte orders, and exactly sized buffers so that end-of-buffer read paths are hit.
 */
class ChunkInputRoundTripTest {

	private static final int ELEMENTS = 4;
	private static final int MAX_UNCACHED_TUPLES = 70;
	private static final ByteOrder[] ORDERS = { ByteOrder.LITTLE_ENDIAN, ByteOrder.BIG_ENDIAN };

	@Test
	void decodesRandomChunks() {
		SplittableRandom random = new SplittableRandom(4711);
		int checked = 0;
		for (int round = 0; round < 400; round++) {
			for (int splitPoint = 0; splitPoint < ELEMENTS; splitPoint++) {
				int size = 1 + random.nextInt(MAX_UNCACHED_TUPLES);
				long[][] tuples = generate(random, size, splitPoint);
				for (ByteOrder order : ORDERS) {
					for (boolean direct : new boolean[] { false, true }) {
						ByteBuffer[] encoded = encode(tuples, splitPoint, order, direct);
						verifyIteration(new ChunkInput(encoded[0].duplicate().order(order),
								encoded[1].duplicate().order(order), ELEMENTS, splitPoint), tuples);
						if (size <= Chunks.MAX_CHUNK_SIZE) {
							verifyCached(encoded, order, tuples, splitPoint, random);
						}
						verifySeek(encoded, order, tuples, splitPoint, random);
						checked++;
					}
				}
			}
		}
		assertTrue(checked > 0);
	}

	private static void verifyIteration(ChunkInput input, long[][] tuples) {
		for (long[] tuple : tuples) {
			assertArrayEquals(tuple, Arrays.copyOf(input.next(), ELEMENTS));
		}
		assertNull(input.next());
	}

	private static void verifyCached(ByteBuffer[] encoded, ByteOrder order, long[][] tuples, int splitPoint,
			SplittableRandom random) {
		ChunkInput input = new ChunkInput();
		input.reset(encoded[0].duplicate().order(order), encoded[1].duplicate().order(order), ELEMENTS, splitPoint);
		int partial = random.nextInt(tuples.length + 1);
		for (int i = 0; i < partial; i++) {
			assertArrayEquals(tuples[i], Arrays.copyOf(input.next(), ELEMENTS));
		}
		input.rewind();
		verifyIteration(input, tuples);
		input.rewind();
		verifyIteration(input, tuples);
	}

	private static void verifySeek(ByteBuffer[] encoded, ByteOrder order, long[][] tuples, int splitPoint,
			SplittableRandom random) {
		int target = random.nextInt(tuples.length);
		ChunkInput input = new ChunkInput(encoded[0].duplicate().order(order), encoded[1].duplicate().order(order),
				ELEMENTS, splitPoint);
		assertEquals(0, input.seek(tuples[target]));
		assertArrayEquals(tuples[target], Arrays.copyOf(input.current(), ELEMENTS));
		for (int i = target; i < tuples.length; i++) {
			assertArrayEquals(tuples[i], Arrays.copyOf(input.next(), ELEMENTS));
		}
		assertNull(input.next());
	}

	private static long[][] generate(SplittableRandom random, int size, int splitPoint) {
		long[] prefix = new long[splitPoint];
		for (int i = 0; i < splitPoint; i++) {
			prefix[i] = randomValue(random);
		}
		// Per column magnitude: small values favour packed or constant columns, mixed magnitudes favour varint.
		int[] maxBits = new int[ELEMENTS];
		boolean[] constant = new boolean[ELEMENTS];
		for (int e = splitPoint; e < ELEMENTS; e++) {
			maxBits[e] = 1 + random.nextInt(62);
			constant[e] = random.nextInt(6) == 0;
		}
		long[] constants = new long[ELEMENTS];
		for (int e = 0; e < ELEMENTS; e++) {
			constants[e] = randomValue(random);
		}
		long[][] tuples = new long[size][];
		for (int t = 0; t < size; t++) {
			long[] tuple = new long[ELEMENTS];
			System.arraycopy(prefix, 0, tuple, 0, splitPoint);
			for (int e = splitPoint; e < ELEMENTS; e++) {
				if (constant[e]) {
					tuple[e] = constants[e];
				} else if (random.nextInt(4) == 0) {
					tuple[e] = randomValue(random);
				} else {
					tuple[e] = random.nextLong(1L << maxBits[e]);
				}
			}
			tuples[t] = tuple;
		}
		Arrays.sort(tuples, Chunks::compareTuples);
		// ChunkOutput expects distinct tuples
		int distinct = 1;
		for (int t = 1; t < size; t++) {
			if (Chunks.compareTuples(tuples[t], tuples[distinct - 1]) != 0) {
				tuples[distinct++] = tuples[t];
			}
		}
		return Arrays.copyOf(tuples, distinct);
	}

	/** Returns a value whose varint length is uniformly distributed over all possible lengths. */
	private static long randomValue(SplittableRandom random) {
		int bits = random.nextInt(63);
		return bits == 0 ? 0 : (1L << (bits - 1)) | random.nextLong(1L << (bits - 1));
	}

	private static ByteBuffer[] encode(long[][] tuples, int splitPoint, ByteOrder order, boolean direct) {
		ChunkOutput output = new ChunkOutput(Math.max(tuples.length, 1), ELEMENTS, splitPoint);
		for (long[] tuple : tuples) {
			assertTrue(output.addTuple(tuple));
		}
		ByteBuffer key = ByteBuffer.allocate(128).order(order);
		ByteBuffer value = ByteBuffer.allocate(16 * 1024).order(order);
		output.write(key, value);
		return new ByteBuffer[] { exact(key.flip(), order, direct), exact(value.flip(), order, direct) };
	}

	private static ByteBuffer exact(ByteBuffer source, ByteOrder order, boolean direct) {
		ByteBuffer copy = direct ? ByteBuffer.allocateDirect(source.remaining())
				: ByteBuffer.allocate(source.remaining());
		copy.put(source).flip();
		return copy.order(order);
	}
}
